/** Generated by the NeuralCommons App Generator (layer: frontend). */

import { apiGet } from "../lib/api";

export default async function Overview() {
  const dictionary = await apiGet("/dictionary");
  const instruments = await apiGet("/instruments");

  return (
    <main>
      <section className="panel">
        <h2>Genesis dictionary</h2>
        {dictionary.ok ? (
          <>
            <p>{dictionary.data.name}</p>
            <p className="mono muted">{dictionary.data.cid}</p>
            <p className="muted">namespace {dictionary.data.namespace}</p>
          </>
        ) : (
          <p className="muted">API unreachable — start the backend and reload.</p>
        )}
      </section>

      <section className="panel">
        <h2>Latest instruments</h2>
        {!instruments.ok ? (
          <p className="muted">API unreachable — start the backend and reload.</p>
        ) : instruments.data.count === 0 ? (
          <p className="muted">no instruments yet</p>
        ) : (
          <ul className="plain">
            {instruments.data.instruments.slice(0, 5).map((row) => (
              <li key={row.cid}>
                <strong>{row.instrument}</strong> · {row.trust}{" "}
                <div className="mono muted">{row.cid}</div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  );
}
